@push('scripts')<script>$(function(){const codes=@json(collect($whtTaxCodes ?? [])->map(fn($code)=>['id'=>$code->id,'label'=>$code->code.' · '.$code->name.' ('.$code->rate.'%)','rate'=>(float)$code->rate])->values()),form=$('[data-physical-sale-form]');if(!form.length)return;const options=['<option value="">ไม่หัก ณ ที่จ่าย</option>'].concat(codes.map(code=>'<option value="'+code.id+'" data-rate="'+code.rate+'">'+$('<span>').text(code.label).html()+'</option>')).join('');const section=$('<div class="col-12 js-physical-sale-wht"><div class="border rounded-3 p-3 bg-body-tertiary"><div class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">ภาษีหัก ณ ที่จ่าย</label><select class="form-select" name="withholding_tax_code_id">'+options+'</select><div class="form-text">เลือกเมื่อผู้ซื้อหักภาษี ณ ที่จ่าย</div></div><div class="col-md-4 js-wht-detail d-none"><label class="form-label">ฐานหัก ณ ที่จ่าย</label><input class="form-control text-end" type="number" min="0" step="0.01" name="withholding_base" value="0.00"><div class="form-text">ยอดที่ใช้คำนวณ WHT</div></div><div class="col-md-4 js-wht-detail d-none"><label class="form-label">ยอดหัก ณ ที่จ่าย</label><input class="form-control text-end" type="text" readonly value="0.00"><div class="form-text js-wht-rate"></div></div></div></div></div>');form.find('[name="description"]').closest('.col-12').after(section);const code=section.find('[name="withholding_tax_code_id"]'),detail=section.find('.js-wht-detail'),base=section.find('[name="withholding_base"]'),amount=section.find('[readonly]'),rate=section.find('.js-wht-rate');function sync(clear){const option=code.find(':selected'),percent=Number(option.data('rate')||0),enabled=!!code.val();detail.toggleClass('d-none',!enabled).find('[name="withholding_base"]').prop('disabled',!enabled);if(!enabled&&clear)base.val('0.00');amount.val(enabled?(Number(base.val()||0)*percent/100).toFixed(2):'0.00');rate.text(enabled?'อัตรา '+percent+'% · ระบบคำนวณยอดให้':'');}code.on('change',()=>sync(true));base.on('input',()=>sync(false));sync(false);});</script>@endpush
