<script>
$(function () {
    const $form = $('[data-physical-sale-form]'), $calculation = $('#physical-sale-tax-treatment');
    if (!$form.length || !$calculation.length) return;

    const vatCodes = @json($vatTaxCodes->map(fn ($code) => ['id' => $code->id, 'label' => $code->code.' · '.$code->name, 'rate' => (float) $code->rate])->values());
    const $field = $('<div class="col-md-3 js-physical-sale-vat-code"><label class="form-label">Tax Code ภาษีขาย <span class="text-danger">*</span></label><select class="form-select" name="tax_code_id"><option value="">เลือก Tax Code ภาษีขาย</option></select><div class="form-text js-vat-code-help"></div><div class="invalid-feedback" data-error-for="tax_code_id"></div></div>');
    const $code = $field.find('[name="tax_code_id"]'), $help = $field.find('.js-vat-code-help');
    vatCodes.forEach(code => $code.append($('<option>').val(code.id).attr('data-rate', code.rate).text(`${code.label} (${code.rate}%)`)));
    $code.val(@json(old('tax_code_id', $sale->tax_code_id)));
    $calculation.closest('.col-md-3').after($field);

    function syncVatCode() {
        const noneVat = $calculation.val() === 'NONE';
        $field.toggleClass('d-none', noneVat);
        $code.prop('disabled', noneVat).prop('required', !noneVat);
        if (noneVat) $code.val('');
        const rate = $code.find(':selected').data('rate');
        $('#physical-sale-tax-help').text(noneVat ? 'ไม่มี VAT: ไม่ต้องเลือก Tax Code ภาษีขาย และยอดภาษีจะเป็น 0.00' : 'เลือกวิธีคำนวณภาษีและ Tax Code ให้ตรงกับใบสั่งขาย');
        $help.text(noneVat ? '' : (rate === undefined ? 'กรุณาเลือก Tax Code ภาษีขาย' : `อัตรา VAT ${rate}% · ระบบคำนวณฐานภาษี ภาษี และยอดรวมจากรายการสินค้าเมื่อบันทึกร่าง`));
    }

    $calculation.on('change', syncVatCode);
    $code.on('change', syncVatCode);
    syncVatCode();
});
</script>
